// band_arr.mjs: the arrangement.  Every event of every player, bar by bar, on the film's grid (160 BPM, bar = 36 frames = 16 sixteenths).
import { nt, rng, F } from './inst_core.mjs';
export const S16 = 0.09375, BAR = 1.5;
export const at = (bar, p = 0) => bar * BAR + p * S16;
const X = {};
const R = rng('arr');
const put = (k, e) => { (X[k] ||= []).push(e); };
export const clear = () => { for (const k in X) delete X[k]; };
// "D5:4 F5+A5:2@.8 r:2" : notes, length in 16ths, velocity
function seq(inst, bar, p, str, o = {}) { let q = p; for (const tok of str.trim().split(/\s+/)) { const m = /^([^:]+):([\d.]+)(?:@([\d.]+))?(?:!(\w+))?$/.exec(tok); if (!m) throw new Error('seq ' + tok); const len = +m[2], v = m[3] ? +m[3] : (o.v ?? .7); if (m[1] !== 'r') { const notes = m[1].split('+').map(nt); for (let k = 0; k < notes.length; k++) { const e = { ...o, t: at(bar, q) + (o.roll ? o.roll * k : 0), dur: len * S16 * (o.leg ?? .96), n: notes[k] + (o.tr || 0), v: v * (o.vf ? o.vf(q) : 1) }; if (m[4]) e.art = m[4]; delete e.vf; delete e.tr; put(inst, e); } } q += len; } return q; }
const ch = (inst, bar, p, notes, len, v, o = {}) => { notes.split(' ').forEach((s, k) => put(inst, { ...o, t: at(bar, p) + (o.roll || 0) * k, dur: len * S16 * (o.leg ?? .98), n: nt(s), v })); };
// drum patterns: one char per 16th, digits = velocity/9
function dr(bar, pats, o = {}) { for (const pc in pats) { const s = pats[pc]; if (s.length > 16) throw new Error('pattern ' + bar + pc + s); for (let i = 0; i < s.length; i++) { const c = s[i]; if (c >= '1' && c <= '9') put(o.kit || 'kit', { t: at(bar, i), p: pc, v: (+c / 9) * (o.v ?? 1), ...(o.x || {}) }); } } }
const hit = (pc, bar, p, v = 1, x = {}) => put('kit', { t: at(bar, p), p: pc, v, ...x });
const tk = (bar, pats, o = {}) => dr(bar, pats, { kit: 'taiko', ...o });
// rolls are played by two hands: accents in groups, weaker left hand, timing that breathes
const roll = (kit, pc, bar, p0, p1, step, v0, v1, pow = 1.5, x = {}) => { let k = 0; const grp = [1.08, .62, .74, .98, .6, .72, 1.04, .7]; for (let p = p0; p < p1 - 1e-6; p += step, k++) { const u = (p - p0) / (p1 - p0), hand = k % 2 ? .86 : 1, acc = step < 1.5 ? grp[k % 8] : (k % 2 ? .8 : 1.05); put(kit, { t: at(bar, p) + (p > p0 ? R.g() * .0042 : 0) - .003 * u, p: pc, v: Math.min(1, (v0 + (v1 - v0) * Math.pow(u, pow)) * hand * acc * (1 + .08 * R.g())), ...x }); } };
// rhythm guitar: X open chord, x palm-muted root, o palm-muted fifth chord, - hold, . rest, V octave dyad, S staccato chord
function rg(bar, root, pat, o = {}) { const k = o.k || 'rg', n = pat.length; let dn = 0; for (let i = 0; i < n; i++) { const c = pat[i]; if (c === '.' || c === '-') continue; let j = i + 1; while (j < n && pat[j] === '-') j++; const len = j - i, t = at(bar, i), v = (o.v ?? .92) * (i % 4 === 0 ? 1.04 : .95); const full = o.notes || [root, root + 7, root + 12]; dn++;
  if (c === 'X') put(k, { t, dur: len * S16 - .004, n: full, v, dir: o.alt && dn % 2 === 0 ? 'u' : 'd' }); else if (c === 'S') put(k, { t, dur: Math.min(.085, len * S16), n: full, v, dir: 'd', tight: 1 }); else if (c === 'x') put(k, { t, dur: len * S16 * .97, n: [root], v: v * .92, pm: .92, dir: (i % 2) ? 'u' : 'd' }); else if (c === 'o') put(k, { t, dur: len * S16 * .97, n: [root, root + 7], v: v * .9, pm: .8, dir: (i % 2) ? 'u' : 'd' }); else if (c === 'V') put(k, { t, dur: len * S16 - .004, n: [root, root + 12], v, dir: 'd' }); } }
