function osti(inst, bar, p0, p1, cyc, o = {}) { const ns = cyc.split(' '); let k = 0; for (let p = p0; p < p1 - 1e-6; p += (o.step || 1), k++) { const u = (p - p0) / (p1 - p0); const s = ns[k % ns.length]; if (s === '.') continue; const ac = o.acc && (k % o.acc === 0) ? 1.18 : 1; for (const q of s.split('+')) put(inst, { t: at(bar, p), dur: (o.step || 1) * S16 * (o.leg ?? .8), n: nt(q), v: ((o.v ?? .6) + ((o.v2 ?? o.v ?? .6) - (o.v ?? .6)) * u) * ac, art: o.art || 'spic' }); } }

